cd /private/tmp/claude-501/-Users-vmysla-src-ab-study-arms-tetris-rep-control-03-control/01b4056d-ee92-459d-a9ce-4dbdcfe673b2/scratchpad && (ls node_modules/playwright >/dev/null 2>&1 || npm i playwright@1.5 --silent >/dev/null 2>&1 || npm i playwright --silent >/dev/null 2>&1) && cat > t.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch(); const p = await b.newPage();
const errs=[]; p.on('pageerror', e=>errs.push(e.message));
await p.goto('file:///Users/vmysla/src/ab-study/arms/tetris-rep-control-03/control/index.html');
const r = await p.evaluate(() => {
  const t = window.__tetris, out = {};
  t.newGame(["I","O","T"]);
  out.s0 = t.getState();
  out.cells = document.querySelectorAll('[data-testid=cell]').length;
  t.input("left"); t.tick(3);
  out.s1 = t.getState().current;
  t.input("hardDrop");
  out.b1 = t.getBoard().slice(18);
  out.s2 = t.getState();
  const c = document.querySelector('[data-row="19"][data-col="2"]');
  out.dom = [c.dataset.filled, c.dataset.piece, getComputedStyle(c).backgroundColor];
  t.setBoard(Array(19).fill("..........").concat(["ZZZZ......"]));
  out.b2 = t.getBoard().slice(19);
  t.tick(30); out.b3 = t.getBoard().slice(17); out.s3 = t.getState();
  out.txt = [score, level, lines].map(()=>0);
  out.txt = ['score','level','lines'].map(id=>document.querySelector(`[data-testid=${id}]`).textContent);
  return out;
});
console.log(JSON.stringify(r, null, 1), errs);
await b.close();
EOF
